//! Pulse: electrical signal that propagates between dots.

use crate::{ChemicalDelta, DotId, PulseId, Rate};
use serde::{Deserialize, Serialize};


/// Where a pulse originated.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum PulseSource {
    /// Legacy data and new external input default to External.
    #[default]
    External,
    /// Generated by the brain's own processing.
    Internal,
}

/// Direction metadata for TRANS pulses.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum TransDirection {
    #[default]
    None,
    In,
    Out,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Pulse {
    pub id: PulseId,
    pub origin: DotId,
    pub value: f64,
    pub intensity: f64,
    pub speed: f64,
    pub pulse_type: PulseType,
    pub chemical_payload: ChemicalDelta,
    pub path_trace: Vec<DotId>,
    pub ttl: u32,
    pub created_tick: u64,
    pub seed: u64,
    /// Spatial, temporal, and channel metadata carried with this pulse.
    /// Defaults when reading snapshots written before this field existed.
    #[serde(default)]
    pub rate: Rate,
    /// Provenance metadata. Missing legacy snapshots deserialize as External.
    #[serde(default)]
    pub source: PulseSource,
    /// TRANS direction. Missing legacy snapshots deserialize as None.
    #[serde(default)]
    pub trans_direction: TransDirection,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub enum PulseType {
    /// V.Pulse — carries computed value forward.
    Value,
    /// R.Pulse — reward/reinforcement (backward).
    Reward,
    /// I.Pulse — inhibitory, suppresses target.
    Inhibitory,
    /// M.Pulse — modulatory, changes parameters.
    Modulatory,
    /// Trans — bidirectional communication.
    Trans,
}

impl Pulse {
    pub fn value_pulse(origin: DotId, value: f64, intensity: f64, tick: u64) -> Self {
        Pulse {
            id: PulseId::next(),
            origin,
            value,
            intensity,
            speed: 1.0,
            pulse_type: PulseType::Value,
            chemical_payload: ChemicalDelta::default(),
            path_trace: vec![origin],
            ttl: 64,
            created_tick: tick,
            seed: 0,
            rate: Rate::default(),
            source: PulseSource::Internal,
            trans_direction: TransDirection::None,
        }
    }

    pub fn reward_pulse(origin: DotId, reward_value: f64, tick: u64) -> Self {
        Pulse {
            id: PulseId::next(),
            origin,
            value: reward_value,
            intensity: reward_value.abs(),
            speed: 2.0,
            pulse_type: PulseType::Reward,
            chemical_payload: ChemicalDelta::reward(reward_value),
            path_trace: vec![origin],
            ttl: 128,
            created_tick: tick,
            seed: 0,
            rate: Rate::default(),
            source: PulseSource::Internal,
            trans_direction: TransDirection::None,
        }
    }

    pub fn inhibitory_pulse(origin: DotId, value: f64, tick: u64) -> Self {
        Pulse {
            id: PulseId::next(),
            origin,
            value: -value.abs(),
            intensity: value.abs(),
            speed: 1.5,
            pulse_type: PulseType::Inhibitory,
            chemical_payload: ChemicalDelta {
                gaba: value.abs() * 0.5,
                ..Default::default()
            },
            path_trace: vec![origin],
            ttl: 32,
            created_tick: tick,
            seed: 0,
            rate: Rate::default(),
            source: PulseSource::Internal,
            trans_direction: TransDirection::None,
        }
    }


    /// Construct an internal pulse of the requested type.
    pub fn new_internal(origin: DotId, value: f64, pulse_type: PulseType, tick: u64) -> Self {
        let mut pulse = Self::value_pulse(origin, value, value.abs(), tick);
        pulse.pulse_type = pulse_type;
        pulse.source = PulseSource::Internal;
        pulse
    }

    /// Construct a pulse received from an external source.
    pub fn new_external(origin: DotId, value: f64, pulse_type: PulseType, tick: u64) -> Self {
        let mut pulse = Self::value_pulse(origin, value, value.abs(), tick);
        pulse.pulse_type = pulse_type;
        pulse.source = PulseSource::External;
        pulse
    }

    /// Construct an inbound TRANS pulse.
    pub fn new_trans_in(origin: DotId, value: f64, tick: u64, source: PulseSource) -> Self {
        let mut pulse = Self::value_pulse(origin, value, value.abs(), tick);
        pulse.pulse_type = PulseType::Trans;
        pulse.source = source;
        pulse.trans_direction = TransDirection::In;
        pulse
    }

    /// Construct an outbound TRANS pulse.
    pub fn new_trans_out(origin: DotId, value: f64, tick: u64, source: PulseSource) -> Self {
        let mut pulse = Self::value_pulse(origin, value, value.abs(), tick);
        pulse.pulse_type = PulseType::Trans;
        pulse.source = source;
        pulse.trans_direction = TransDirection::Out;
        pulse
    }

    pub fn is_external(&self) -> bool { self.source == PulseSource::External }
    pub fn is_internal(&self) -> bool { self.source == PulseSource::Internal }
    pub fn is_trans(&self) -> bool { self.pulse_type == PulseType::Trans }

    /// Record that this pulse passed through a dot.
    pub fn trace(&mut self, dot_id: DotId) {
        self.path_trace.push(dot_id);
        self.ttl = self.ttl.saturating_sub(1);
    }

    /// Check if this pulse is still alive.
    pub fn is_alive(&self) -> bool {
        self.ttl > 0
    }

    /// Check if this pulse already visited a dot (loop prevention).
    pub fn has_visited(&self, dot_id: DotId) -> bool {
        self.path_trace.contains(&dot_id)
    }
}
